package com.workspace.collab.controller;

import com.workspace.collab.dto.MemberPatchDto;
import com.workspace.collab.entity.WorkspaceMember;
import com.workspace.collab.mapper.WorkspaceMemberMapper;
import com.workspace.collab.repository.WorkspaceMemberRepository;
import com.workspace.collab.service.WorkspaceSecurityService;
import org.springframework.http.ResponseEntity;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.security.core.Authentication;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/api/workspaces/{wsId}/members")
public class MemberUpdateController {

    private final WorkspaceMemberRepository memberRepository;
    private final WorkspaceMemberMapper memberMapper;
    private final WorkspaceSecurityService securityService;

    public MemberUpdateController(WorkspaceMemberRepository memberRepository, WorkspaceMemberMapper memberMapper, WorkspaceSecurityService securityService) {
        this.memberRepository = memberRepository;
        this.memberMapper = memberMapper;
        this.securityService = securityService;
    }

    @PatchMapping("/{memberId}")
    public ResponseEntity<String> updateMemberProfile(
            @PathVariable String wsId,
            @PathVariable Long memberId,
            @RequestBody MemberPatchDto patchDto,
            Authentication authentication) {
        WorkspaceMember member = memberRepository.findById(memberId)
                .orElseThrow(() -> new IllegalArgumentException("Member not found"));
        if (!member.getWorkspaceId().equals(wsId)) {
            throw new IllegalArgumentException("Member does not belong to workspace " + wsId);
        }
        if (patchDto.getSecurityClearanceLevel() != null && !securityService.isWorkspaceAdmin(authentication.getName(), wsId)) {
            throw new AccessDeniedException("Only workspace administrators can modify clearance levels");
        }
        memberMapper.updateMemberFromDto(patchDto, member);
        memberRepository.save(member);
        return ResponseEntity.ok("Member profile patched");
    }
}
